import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(T):
        try:
            N = int(next(iterator))
            A = []
            for _ in range(N):
                A.append(int(next(iterator)))
        except StopIteration:
            break

        if N == 0:
            results.append("0 0")
            continue

        def count_inversions(arr):
            count = 0
            n = len(arr)
            sorted_arr = sorted(arr)
            rank_map = {}
            current_rank = 0
            for x in sorted_arr:
                if x not in rank_map:
                    rank_map[x] = current_rank
                    current_rank += 1

            bit = [0] * (n + 1)

            def update(idx):
                idx += 1
                while idx <= n:
                    bit[idx] += 1
                    idx += idx & (-idx)

            def query(idx):
                idx += 1
                s = 0
                while idx > 0:
                    s += bit[idx]
                    idx -= idx & (-idx)
                return s

            total_inv = 0
            processed_count = 0
            for i in range(n - 1, -1, -1):
                r = rank_map[arr[i]]
                total_inv += query(r - 1)
                update(r)

            return total_inv

        base_inv = count_inversions(A)

        max_inv = base_inv
        best_idx = 0

        current_inv = base_inv
        if N > 1:
            for k in range(1, N):
                prev_val = A[k - 1]
                current_inv -= (k - 1) - sum(1 for x in A[k:] if x < prev_val)
                current_inv += sum(1 for x in A[:k] if x > prev_val)

                if current_inv > max_inv:
                    max_inv = current_inv
                    best_idx = k
                elif current_inv == max_inv:
                    if best_idx == -1:
                        best_idx = k
                    else:
                        curr_rot = A[k:] + A[:k]
                        best_rot = A[best_idx:] + A[:best_idx]
                        if curr_rot < best_rot:
                            best_idx = k

        results.append(f"{best_idx} {max_inv}")

    for res in results:
        print(res)

if __name__ == "__main__":
    solve()
